import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { join } from 'node:path';
const moduleURL = pathToFileURL(join(process.env.AF_WORKSPACE, 'format.js')).href;
test('consumer precision overrides never change later defaults', async () => {
  const { formatAmount } = await import(moduleURL);
  assert.equal(formatAmount(12.375), '12.38');
  for (const [value, zero, standard, three] of [[12.375, '12', '12.38', '12.375'], [7.875, '8', '7.88', '7.875'], [12.375, '12', '12.38', '12.375']]) {
    assert.equal(formatAmount(value, {precision: 0}), zero);
    assert.equal(formatAmount(value), standard);
    assert.equal(formatAmount(value, {precision: 3}), three);
    assert.equal(formatAmount(value), standard);
  }
});
test('two isolated consumer call orders retain their own default precision', () => {
  const sequences = [
    { calls: [[12.375, {precision: 0}], [12.375], [7.875, {precision: 3}], [7.875]], expected: ['12', '12.38', '7.875', '7.88'] },
    { calls: [[7.875, {precision: 3}], [7.875], [12.375, {precision: 0}], [12.375]], expected: ['7.875', '7.88', '12', '12.38'] }
  ];
  for (const {calls, expected} of sequences) {
    const source = 'import {formatAmount} from ' + JSON.stringify(moduleURL) + '; const calls=' + JSON.stringify(calls) + '; console.log(JSON.stringify(calls.map(args=>formatAmount(...args))));';
    const result = spawnSync(process.execPath, ['--input-type=module', '--eval', source], {encoding: 'utf8', timeout: 5000});
    assert.ifError(result.error);
    assert.equal(result.status, 0, result.stderr);
    assert.equal(result.stderr.trim(), '');
    assert.deepEqual(JSON.parse(result.stdout), expected);
  }
});

files.stats.js:
export function summarize(values) {
  return { count: values.length };
}

files.cli.js:
import { readFileSync } from 'node:fs';
import { summarize } from './stats.js';
const file = process.argv[2];
if (!file) { console.error('Usage: node cli.js FILE'); process.exit(1); }
try {
  const values = JSON.parse(readFileSync(file, 'utf8'));
  console.log('Count: ' + summarize(values).count);
} catch (error) { console.error(error.message); process.exitCode = 1; }

