import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { copyFileSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
test('only the three shipped files deliver the public API and real CLI', async () => {
  const temporary = mkdtempSync(join(tmpdir(), 'af-stats-deployment-'));
  try {
    const deployed = join(temporary, 'deployment');
    mkdirSync(deployed);
    for (const name of ['package.json', 'stats.js', 'cli.js']) copyFileSync(join(process.env.AF_WORKSPACE, name), join(deployed, name));
    const { summarize } = await import(pathToFileURL(join(deployed, 'stats.js')));
    const input = join(temporary, 'values.json');
    const run = args => spawnSync(process.execPath, [join(deployed, 'cli.js'), ...args], {cwd: deployed, encoding: 'utf8', timeout: 5000});
    function success(result) {
      assert.ifError(result.error);
      assert.equal(result.status, 0, result.stderr);
      assert.equal(result.stderr.trim(), '');
    }
    function failure(result, message) {
      assert.ifError(result.error);
      assert.equal(result.signal, null);
      assert.notEqual(result.status, 0, 'invalid input succeeded: ' + result.stdout);
      assert.equal(result.stdout.trim(), '', 'failure emitted success output');
      assert.match(result.stderr, message);
      assert.doesNotMatch(result.stderr, /^\s+at\s/m, 'a stack trace leaked');
    }
    const scenarios = [
      {values: [-2.5, 1, 4.5], expected: {count: 3, sum: 3, average: 1}},
      {values: [0, -6, 1.5, 2.5], expected: {count: 4, sum: -2, average: -0.5}},
      {values: [], expected: {count: 0, sum: 0, average: 0}},
      {values: [0.125], expected: {count: 1, sum: 0.125, average: 0.125}}
    ];
    for (const {values, expected} of scenarios) {
      const original = [...values];
      assert.deepEqual(summarize(values), expected);
      assert.deepEqual(values, original, 'summarize mutated its input');
      writeFileSync(input, JSON.stringify(values));
      const plain = run([input]);
      success(plain);
      assert.equal(plain.stdout, 'Count: ' + expected.count + '\nSum: ' + expected.sum + '\nAverage: ' + expected.average + '\n');
      const json = run([input, '--json']);
      success(json);
      assert.deepEqual(JSON.parse(json.stdout), expected);
    }
    writeFileSync(input, '[1,2]');
    for (const args of [[], ['--json']]) failure(run(args), /usage|file|missing|required/i);
    for (const args of [[input, '--yaml'], [input, '--json', '--wat'], [input, 'extra.json']]) failure(run(args), /unknown|option|argument|usage|unexpected/i);
    failure(run([join(temporary, 'absent.json')]), /file|read|ENOENT|no such/i);
    for (const invalid of ['[1,"2"]', '[null]', '[true]', '{}', 'null', 'not json', '[1e400]']) {
      writeFileSync(input, invalid);
      failure(run([input]), /number|numeric|finite|array|json|parse|data|invalid|unexpected/i);
      failure(run([input, '--json']), /number|numeric|finite|array|json|parse|data|invalid|unexpected/i);
    }
  } finally {
    rmSync(temporary, {recursive: true, force: true});
  }
});

